    // Add consumed column\n        await queryRunner.addColumn(\n            \"session\",\n            new TableColumn({\n                name: \"consumed\",\n                type: \"boolean\",\n                default: false,\n                isNullable: false,\n            }),\n        );\n\n        // Add consumedAt column\n        await queryRunner.addColumn(\n            \"session\",\n            new TableColumn({\n                name: \"consumedAt\",\n                type:\n                    queryRunner.connection.driver.options.type ===\n                    \"better-sqlite3\"\n                        ? \"datetime\"\n                        : \"timestamp\",\n                isNullable: true,\n            }),\n        );\n    }\n\n    public async down(queryRunner: QueryRunner): Promise {\n        const table = await queryRunner.getTable(\"session\");\n        if (!table) {\n            console.log(\n                \"[Migration] session table not found — skipping (schema may not exist yet).\",\n            );\n            return;\n        }\n\n        const hasConsumedColumn = table.columns.some(\n            (col) => col.name === \"consumed\",\n        );\n        if (hasConsumedColumn) {\n            await queryRunner.dropColumn(\"session\", \"consumed\");\n        }\n\n        const hasConsumedAtColumn = table.columns.some(\n            (col) => col.name === \"consumedAt\",\n        );\n        if (hasConsumedAtColumn) {\n            await queryRunner.dropColumn(\"session\", \"consumedAt\");\n        }\n    }\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"classes/AddSigningKeyIdToIssuanceConfig1741000000000.html":{"url":"classes/AddSigningKeyIdToIssuanceConfig1741000000000.html","title":"class - AddSigningKeyIdToIssuanceConfig1741000000000","body":"\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n  Classes\n  AddSigningKeyIdToIssuanceC